// Packages: AWSSDK.SecretsManager, Amazon.SecretsManager
using Amazon.SecretsManager;
using Amazon.SecretsManager.Model;

public static async Task<string> GetSecretWithIamRoleAsync(
    string secretName,
    CancellationToken cancellationToken = default)
{
    try
    {
        // When running on EC2/ECS with an assigned IAM role, no access keys needed
        var secretsClient = new SecretsManagerClient(RegionEndpoint.USEast1);

        var response = await secretsClient.GetSecretValueAsync(secretName, cancellationToken);
        string connectionString = response.SecretString;
        Console.WriteLine($"Retrieved secret via IAM role: {secretName}");

        return connectionString;
    }
    catch (AmazonSecretsManagerException ex)
    {
        Console.WriteLine($"Access denied or secret not found: {ex.Message}");
        throw;
    }
}

